<template>
  <view class="live-page live-ui">
    <view class="live-heading"><view><text class="live-eyebrow">清诉 · 计划</text><text class="live-title">健康计划</text></view><button role="button" tabindex="0" @keydown="activateButton" class="live-primary" :disabled="!auth.isLoggedIn" @click="newSchedule">新增用药计划</button></view>
    <view v-if="!auth.isLoggedIn" class="live-card live-blank"><QIcon name="calendar" /><text>登录后查看自己的健康计划</text><button role="button" tabindex="0" @keydown="activateButton" class="live-primary" @click="workspace.accountOpen = true">登录账户</button></view>
    <template v-else>
      <view class="live-row plan-toolbar"><picker mode="date" :value="day" @change="day = String($event.detail.value); load()"><view class="day-picker"><QIcon name="calendar" /><text>{{ dates[0] }} 至 {{ dates[6] }}</text></view></picker><button role="button" tabindex="0" @keydown="activateButton" class="live-link" :disabled="loading" @click="showUpcoming">未来 7 天</button><button role="button" tabindex="0" @keydown="activateButton" class="live-link" :disabled="loading" @click="load">刷新</button></view>
      <view class="live-tabs" role="tablist" aria-label="计划类型"><button v-for="tab in tabs" :key="tab.id" role="tab" tabindex="0" @keydown="activateButton" :aria-selected="workspace.selectedPlanTab === tab.id" :class="{ active: workspace.selectedPlanTab === tab.id }" @click="workspace.selectedPlanTab = tab.id">{{ tab.title }}</button></view>
      <text v-if="error" class="live-error" role="alert">{{ error }}</text><text v-if="loading" class="live-muted" role="status">正在读取健康计划…</text>
      <view v-if="scheduleOpen" class="live-card"><text class="live-subtitle">{{ scheduleId ? '编辑用药计划' : '新增用药计划' }}</text><text class="live-muted">提醒按本人已有用药记录设置；保存问诊后可安排随访与就诊提醒。</text><view class="live-grid"><view class="live-full"><text class="live-label">已有用药记录 *</text><picker :range="medicineNames" :value="medicineIndex" :disabled="Boolean(scheduleId)" @change="form.medication_id = medications[Number($event.detail.value)]?.id || 0"><view class="live-select">{{ medicineIndex >= 0 ? medicineNames[medicineIndex] : '选择已有记录' }}</view></picker><button v-if="!medications.length" role="button" tabindex="0" @keydown="activateButton" class="live-link" @click="$emit('open-archive')">先去健康档案添加用药记录</button></view><view class="live-full"><label class="live-label" for="schedule-times">提醒时间（最多 4 项，逗号分隔）*</label><input id="schedule-times" v-model="form.times" class="live-input" maxlength="28" placeholder="08:00,20:00" /></view><view><text class="live-label">开始日期 *</text><picker mode="date" :value="form.started_on" @change="form.started_on = String($event.detail.value)"><view class="live-select">{{ form.started_on }}</view></picker></view><view><text class="live-label">结束日期（选填）</text><picker mode="date" :value="form.ended_on" @change="form.ended_on = String($event.detail.value)"><view class="live-select">{{ form.ended_on || '未填写' }}</view></picker><button role="button" tabindex="0" @keydown="activateButton" class="live-link" @click="form.ended_on = ''">清除结束日期</button></view><view class="live-full"><label class="live-label" for="schedule-note">备注（选填）</label><textarea id="schedule-note" v-model="form.note" class="live-textarea" maxlength="200" /></view></view><view class="live-actions"><button role="button" tabindex="0" @keydown="activateButton" class="live-primary" :disabled="busy" @click="submitSchedule">保存计划</button><button role="button" tabindex="0" @keydown="activateButton" class="live-secondary" @click="scheduleOpen = false">取消</button></view></view>
      <view v-for="reminder in filteredReminders" :key="`reminder-${reminder.id}`" class="live-card"><view class="live-row"><view><text class="live-subtitle">{{ reminder.title }}</text><text class="live-muted">{{ reminder.due_at }} · {{ kindLabel(reminder.kind) }}</text></view><text class="live-pill">{{ statusLabel(reminder.status) }}</text></view><text v-if="reminder.body" class="reminder-body">{{ reminder.body }}</text><view v-if="reminder.status === 'pending'" class="live-actions"><template v-if="reminder.kind === 'medication'"><button role="button" tabindex="0" @keydown="activateButton" class="live-primary" :disabled="busy" @click="respond(reminder, 'taken')">已服用</button><button role="button" tabindex="0" @keydown="activateButton" class="live-secondary" :disabled="busy" @click="respond(reminder, 'skipped')">本次跳过</button><button role="button" tabindex="0" @keydown="activateButton" class="live-link" :disabled="busy" @click="respond(reminder, 'snooze')">稍后提醒</button></template><button v-else-if="reminder.kind === 'followup'" role="button" tabindex="0" @keydown="activateButton" class="live-primary" @click="$emit('open-followup', reminder)">开始随访</button><template v-else><button role="button" tabindex="0" @keydown="activateButton" class="live-primary" :disabled="busy" @click="respond(reminder, 'visited')">已就诊</button><button role="button" tabindex="0" @keydown="activateButton" class="live-secondary" :disabled="busy" @click="respond(reminder, 'planned')">计划就诊</button><button role="button" tabindex="0" @keydown="activateButton" class="live-secondary" :disabled="busy" @click="respond(reminder, 'improved')">已好转</button></template></view></view>
      <template v-if="workspace.selectedPlanTab !== 'follow_up'"><view v-for="schedule in schedules" :key="`schedule-${schedule.id}`" class="live-card"><view class="live-row"><view><text class="live-subtitle">{{ medicationName(schedule.medication_id) }}</text><text class="live-muted">{{ schedule.times.join(' / ') }} · {{ schedule.started_on }} 至 {{ schedule.ended_on || '未设结束日期' }}</text></view><text class="live-pill">{{ schedule.status === 'active' ? '进行中' : '已暂停' }}</text></view><text v-if="schedule.note" class="reminder-body">{{ schedule.note }}</text><view class="live-actions"><button role="button" tabindex="0" @keydown="activateButton" class="live-link" @click="editSchedule(schedule)">编辑</button><button role="button" tabindex="0" @keydown="activateButton" class="live-link" :disabled="busy" @click="toggleSchedule(schedule)">{{ schedule.status === 'stopped' ? '恢复提醒' : '暂停提醒' }}</button><button role="button" tabindex="0" @keydown="activateButton" class="live-link" :disabled="busy" @click="removeSchedule(schedule.id)">删除计划</button></view></view></template>
      <view v-if="!loading && !filteredReminders.length && (workspace.selectedPlanTab === 'follow_up' || !schedules.length)" class="live-card live-blank"><text>这 7 天暂无对应提醒。</text><text class="live-muted">随访与复查提醒在保存问诊时生成。</text></view>
    </template>
  </view>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { activateButton } from '@/components/buttonKeyboard'
import QIcon from '@/components/QIcon.vue'
import { useLiveWorkspaceStore } from '@/stores/liveWorkspace'
import { getReminders, respondReminder, type ReminderItem } from '@/api/archive'
import { getMedications, type Medication } from '@/api/medications'
import { listSchedules, createSchedule, updateSchedule, deleteSchedule, type MedicationSchedule } from '@/api/health'
defineEmits<{ (e: 'open-followup', reminder: ReminderItem): void; (e: 'open-archive'): void }>()
const workspace = useLiveWorkspaceStore(), auth = workspace.auth
const today = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10)
const tabs = [{ id: 'all', title: '全部计划' }, { id: 'follow_up', title: '随访与复查' }, { id: 'medication', title: '用药计划' }] as const
const day = ref(today), error = ref(''), busy = ref(false), loading = ref(false), scheduleOpen = ref(false), scheduleId = ref<number | undefined>()
const dates = computed(() => Array.from({ length: 7 }, (_, offset) => new Date(Date.parse(`${day.value}T00:00:00Z`) + offset * 86400000).toISOString().slice(0, 10)))
const reminders = ref<ReminderItem[]>([]), schedules = ref<MedicationSchedule[]>([]), medications = ref<Medication[]>([])
const form = reactive({ medication_id: 0, times: '', started_on: today, ended_on: '', note: '' })
const medicineNames = computed(() => medications.value.map((item) => `${item.name}${item.status !== 'active' ? '（记录非当前）' : ''}`))
const medicineIndex = computed(() => medications.value.findIndex((item) => item.id === form.medication_id))
const filteredReminders = computed(() => reminders.value.filter((item) => workspace.selectedPlanTab === 'all' || (workspace.selectedPlanTab === 'medication' ? item.kind === 'medication' : item.kind !== 'medication')))
let loadVersion = 0
function showUpcoming() { day.value = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10); void load() }
async function load() { if (!auth.isLoggedIn) return; const owner = auth.user?.id, version = ++loadVersion; loading.value = true; error.value = ''; reminders.value = []; try { const [days, plans, medicines] = await Promise.all([Promise.all(dates.value.map((date) => getReminders(date))), listSchedules(), getMedications()]); if (owner !== auth.user?.id || version !== loadVersion) return; reminders.value = days.flatMap((items) => [...items.groups.medication, ...items.groups.followup, ...items.groups.recheck]).sort((a, b) => a.due_at.localeCompare(b.due_at) || a.id - b.id); schedules.value = plans.records; medications.value = medicines.records } catch (cause) { if (owner === auth.user?.id && version === loadVersion) error.value = cause instanceof Error ? cause.message : '读取失败，请重试。' } finally { if (version === loadVersion) loading.value = false } }
async function perform(action: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; try { await action(); await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : '操作失败，请重试。' } finally { busy.value = false } }
onMounted(() => { if (workspace.activeTab === 'plans') void load() })
watch(() => workspace.activeTab, (tab) => { if (tab === 'plans') void load() })
watch(() => auth.user?.id, () => { reminders.value = []; schedules.value = []; medications.value = []; scheduleOpen.value = false; void load() })
function newSchedule() { scheduleId.value = undefined; Object.assign(form, { medication_id: medications.value.find((item) => item.status === 'active')?.id || 0, times: '', started_on: today, ended_on: '', note: '' }); scheduleOpen.value = true }
function editSchedule(item: MedicationSchedule) { scheduleId.value = item.id; Object.assign(form, { ...item, times: item.times.join(','), ended_on: item.ended_on || '', note: item.note || '' }); scheduleOpen.value = true }
function submitSchedule() { void perform(async () => { const times = form.times.split(/[,，、\s]+/).filter(Boolean); if (!form.medication_id || !times.length || times.length > 4 || times.some((value) => !/^([01]\d|2[0-3]):[0-5]\d$/.test(value)) || new Set(times).size !== times.length) throw new Error('请选择用药记录，并填写 1–4 个不重复的 HH:mm 时间。'); const fields = { times, started_on: form.started_on, ended_on: form.ended_on || null, note: form.note }; if (scheduleId.value) await updateSchedule(scheduleId.value, fields); else await createSchedule({ ...fields, medication_id: form.medication_id }); scheduleOpen.value = false }) }
function toggleSchedule(item: MedicationSchedule) { void perform(async () => { await updateSchedule(item.id, { status: item.status === 'stopped' ? 'active' : 'stopped' }) }) }
function removeSchedule(id: number) { uni.showModal({ title: '永久删除此用药提醒计划？', content: '相关未处理提醒也将删除，无法恢复；已有用药记录会保留。', confirmText: '删除', success: (answer) => { if (answer.confirm) void perform(async () => { await deleteSchedule(id) }) } }) }
function respond(item: ReminderItem, action: string) { void perform(async () => { await respondReminder(item.id, { action }) }) }
function medicationName(id: number) { return medications.value.find((item) => item.id === id)?.name || '关联用药记录' }
function statusLabel(status: string) { return ({ pending: '待处理', done: '已处理', skipped: '已跳过', missed: '已错过', expired: '已过期' } as Record<string, string>)[status] || status }
function kindLabel(kind: string) { return kind === 'medication' ? '用药提醒' : kind === 'followup' ? '随访' : '复查' }
</script>

<style scoped>
.day-picker { display: flex; align-items: center; gap: 9px; padding: 9px 0; }
.plan-toolbar { flex-wrap: wrap; justify-content: flex-start; }
.plan-toolbar > picker { flex: 1 1 230px; }
.day-picker .q-icon { width: 18px; height: 18px; }
.reminder-body { display: block; margin-top: 15px; color: #62625b; font-size: 14px; line-height: 1.8; white-space: pre-wrap; }
</style>
